/* state */
const $=id=>document.getElementById(id),esc=x=>displayText(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n||0).toLocaleString('zh-CN'),dec=n=>n==null?'—':Number(n).toFixed(1),pct=(a,b)=>b?Math.round(a/b*100)+'%':'—';let S=null,preview=[],selected=[],tab='home',busy=false,worker,seq=0,jobs=new Map(),lastSave=null,db=null,storageOK=false,search='',rankSort='rank',rankFilter='all',calFilter='upcoming',calLevel='all',histYear=null,showLast=false,auto=false,autoToken=0,profileChoice='scouting',setupSearch='',lastResult=null;
const NAV=[['home','⌂','生涯主页'],['inbox','✉','消息中心'],['players','♙','球员数据库'],['growth','↗','能力发展'],['calendar','▦','参赛计划'],['rank','≡','世界排名'],['history','◷','生涯历史'],['match','▶','比赛中心']];const phaseNames={not_open:'未开放',open:'报名中',accepted:'已截止 · 审核',drawn:'已抽签',completed:'已结束',cancelled:'已取消'},stages={Q1:'资格赛首轮',Q2:'资格赛晋级轮',R64:'64强',R32:'32强',R16:'16强',QF:'四分之一决赛',SF:'半决赛',F:'决赛',G1:'小组赛',G2:'小组赛',G3:'小组赛'},actions={attack:'进攻',net:'网前',control:'拉吊',defense:'防守',serve:'发球',receive:'接发'},terminals={winner:'制胜分',forced_error:'对手受迫失误',unforced_error:'对手非受迫失误'},outcomes={played:'完赛',walkover:'弃权',bye:'轮空',void:'无胜者',retirement:'退赛'};const countries={CHN:'中国',INA:'印尼',JPN:'日本',DEN:'丹麦',THA:'泰国',FRA:'法国',CAN:'加拿大',TPE:'中国台北',MAS:'马来西亚',IND:'印度',HKG:'中国香港',SGP:'新加坡',KOR:'韩国',ENG:'英格兰',IRL:'爱尔兰',BEL:'比利时',GER:'德国',USA:'美国',VIE:'越南',TUR:'土耳其',BUL:'保加利亚',SCO:'苏格兰',UKR:'乌克兰',BRA:'巴西',CZE:'捷克',HUN:'匈牙利',UAE:'阿联酋',PER:'秘鲁',AZE:'阿塞拜疆',SRI:'斯里兰卡'};
function displayText(x){return String(x??'').replace(/（(?:城市)?待定）|\((?:城市)?待定\)/g,'').replace(/暂定|待定/g,'')}
let lookupState=null,lookupPreview=null,playerIndex=new Map(),eventIndex=new Map();
function ensureIndexes(){if(lookupState!==S||(!S&&lookupPreview!==preview)){lookupState=S;lookupPreview=preview;playerIndex=new Map((S?[...S.players,...S.retired]:preview).map(x=>[x.id,x]));eventIndex=new Map((S?.calendar||[]).map(x=>[x.id,x]));}}
function p(id){ensureIndexes();return playerIndex.get(id)}function nm(id){let x=p(id);return x?esc(x.zh||x.name):id==null?'轮空':'#'+id}function full(x){return esc(x.zh||x.name)}function lvl(l){return `<span class="level l${esc(l)}">${l==='WC'?'世锦赛':l==='FINALS'?'总决赛':'S'+esc(l)}</span>`}function ev(id){ensureIndexes();return eventIndex.get(id)}function stage(s){return stages[s]||esc(s||'—')}function matchStage(m,d=null){let st=stage(m.stage);if(!/^G\d+$/.test(m.stage))return st;let i=d?.groups?.findIndex(g=>g.includes(m.a)&&g.includes(m.b))??-1;let group=m.group||(i>=0?String.fromCharCode(65+i):null);return group?`${st} · ${esc(group)}组`:st}function roundLabel(s){return /^G\d+$/.test(s)?`小组赛 · 赛程第${s.slice(1)}轮`:stage(s)}function status(e){return e.status==='completed'?'已结束':e.status==='cancelled'?'已取消':phaseNames[e.phase]||e.phase}function isOwn(id){return id!=null&&id===S?.career_player_id}function badge(t,c=''){return `<span class="badge ${c}">${esc(t)}</span>`}function style(x){return esc(x.profile_style||({attack:'进攻型',defense:'防守型',control:'控制型',net:'网前型',allround:'均衡型'}[x.synthetic_archetype])||'综合型')}
function toast(t,err=false){$('notice').innerHTML=`<div class="toast ${err?'err':''}">${esc(t)}</div>`;clearTimeout(window.tt);window.tt=setTimeout(()=>$('notice').innerHTML='',4200)}function setBusy(v,quiet=false){if(busy===v)return;busy=v;$('busy').innerHTML=v&&!quiet?'<div class="busybar"></div>':'';document.querySelectorAll('button[data-act]').forEach(b=>{if(v&&!b.disabled){b.dataset.wasDisabled='0';b.disabled=true}else if(!v&&b.dataset.wasDisabled==='0'){b.disabled=false;delete b.dataset.wasDisabled}})}
function button(t,js,cl='',disabled=false){return `<button data-act class="${cl}" onclick="${js}" ${disabled?'disabled':''}>${esc(t)}</button>`}function go(t,keepGrowth=false){stopAuto();spatialVisual=null;spatialPaused=false;if(t==='growth'&&!keepGrowth){growthSearch='';growthId=S.career_player_id??null;}if(t==='inbox'&&!S.inbox?.some(x=>x.id===mailId))mailId=null;if(t==='event'){if(S.match)selectEvent(S.match.event_id);eventSection='auto'}tab=t;showLast=false;render();window.scrollTo({top:0,behavior:'instant'})}function page(t,sub,extra=''){return `<div class="pagehead"><div><div class="eyebrow">SMASH V15.4 / ${S.year}</div><h1>${t}</h1><p class="muted" style="margin-top:6px">${sub}</p></div>${extra}</div>`}function modal(t,body){$('modal').innerHTML=`<div class="modalback" onclick="if(event.target===this)closeModal()"><section class="card modal" role="dialog" aria-modal="true" aria-label="${esc(t)}"><div class="modalhead"><h2>${esc(t)}</h2><button onclick="closeModal()" aria-label="关闭">✕</button></div>${body}</section></div>`}function closeModal(){if($('profileLayer')?.innerHTML){closeProfile();return}$('modal').innerHTML=''}document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});


// Full page fullscreen keeps dialogs, score and all match controls accessible.
function pageIsFullscreen(){return !!(document.fullscreenElement||document.webkitFullscreenElement)}
function fullscreenLabel(){return pageIsFullscreen()?'退出全屏':'全屏'}
function syncFullscreenButtons(){document.querySelectorAll('[data-fullscreen]').forEach(b=>{b.textContent=fullscreenLabel();b.setAttribute('aria-pressed',String(pageIsFullscreen()))})}
function fullscreenButton(){return `<button type="button" data-fullscreen aria-label="切换页面全屏" aria-pressed="${pageIsFullscreen()}" onclick="togglePageFullscreen()">${fullscreenLabel()}</button>`}
async function togglePageFullscreen(){try{if(pageIsFullscreen()){const exit=document.exitFullscreen||document.webkitExitFullscreen;if(exit)await exit.call(document);}else{const root=document.documentElement,enter=root.requestFullscreen||root.webkitRequestFullscreen;if(!enter){toast('当前浏览器不支持网页全屏，可使用浏览器全屏或添加到主屏幕。');return;}await enter.call(root);}syncFullscreenButtons();}catch(e){toast('浏览器未允许网页全屏，请使用浏览器的全屏功能。',true)}}
for(const name of ['fullscreenchange','webkitfullscreenchange'])document.addEventListener(name,()=>{syncFullscreenButtons();if(typeof spatialIdle==='function')spatialIdle()});

/* setup */
let setupMode='existing',customDraft=null;
function customData(){if(!customDraft){let keys=Object.keys(preview[0]?.attributes||{});customDraft={name:'',country:'CHN',age:18,height_cm:167,handedness:'right',potential_hidden:99,attributes:Object.fromEntries(keys.map(k=>[k,75]))}}return customDraft}
function customCA(){let a=Object.values(customData().attributes);return .45*a.slice(0,7).reduce((x,y)=>x+y,0)/7+.35*a.slice(7,12).reduce((x,y)=>x+y,0)/5+.20*a.slice(12).reduce((x,y)=>x+y,0)/4}
function setSetupMode(mode){setupMode=mode;render()}
function updateCustom(key,value){customData()[key]=['age','height_cm','potential_hidden'].includes(key)?Number(value):value;updateCustomSummary()}
function updateCustomAttr(i,value,source){let a=customData().attributes,k=Object.keys(a)[i];a[k]=Number(value);let other=document.getElementById((source==='range'?'customNum':'customRange')+i);if(other)other.value=value;updateCustomSummary()}
function setAllCustom(v){for(let k of Object.keys(customData().attributes))customData().attributes[k]=v;render()}
function updateCustomSummary(){let ca=customCA(),d=customData(),a=$('customCA'),pa=$('customPA'),msg=$('customWarning');if(a)a.textContent=Number.isFinite(ca)?ca.toFixed(1):'—';if(pa)pa.textContent=d.potential_hidden;if(msg)msg.textContent=d.potential_hidden+1e-7<ca?'潜力低于当前CA，请提高潜力。':'无总点数限制 · 从零积分开始';}
function customPanel(){let d=customData(),attrs=Object.entries(d.attributes),groups=[['技术能力',0,7],['身体能力',7,12],['心理与决策',12,16]];return `<div class="card stack custom-editor"><div class="row between"><h2>创建自定义球员</h2>${badge('自由编辑','green')}</div><div class="custom-identity"><label>姓名<input id="customName" maxlength="40" placeholder="输入球员姓名" value="${esc(d.name)}" oninput="updateCustom('name',this.value)"></label><label>国家/地区<select onchange="updateCustom('country',this.value)">${Object.entries(countries).map(([k,v])=>`<option value="${k}" ${d.country===k?'selected':''}>${esc(v)} · ${k}</option>`).join('')}</select></label><label>初始年龄<input type="number" min="16" max="40" value="${d.age}" oninput="updateCustom('age',this.value)"></label><label>身高 (cm)<input type="number" min="140" max="200" value="${d.height_cm}" oninput="updateCustom('height_cm',this.value)"></label><label>持拍手<select onchange="updateCustom('handedness',this.value)"><option value="right" ${d.handedness==='right'?'selected':''}>右手</option><option value="left" ${d.handedness==='left'?'selected':''}>左手</option></select></label><label>潜力 PA<input type="number" min="35" max="99" step="0.1" value="${d.potential_hidden}" oninput="updateCustom('potential_hidden',this.value)"></label></div><div class="row between"><h3>16项能力 · 独立设置</h3><div class="row"><button onclick="setAllCustom(75)">全部75</button><button onclick="setAllCustom(99)">全部99</button></div></div>${groups.map(([g,l,r])=>`<section class="custom-group"><h3>${g}</h3>${attrs.slice(l,r).map(([k,v],j)=>`<label class="custom-attr"><span>${esc(k)}</span><input id="customRange${l+j}" aria-label="${esc(k)} 滑块" type="range" min="35" max="99" step="0.1" value="${v}" oninput="updateCustomAttr(${l+j},this.value,'range')"><input id="customNum${l+j}" aria-label="${esc(k)} 数值" type="number" min="35" max="99" step="0.1" value="${v}" oninput="updateCustomAttr(${l+j},this.value,'number')"></label>`).join('')}</section>`).join('')}</div>`}
function customChosen(){return `<div class="row between"><h2>自建球员生涯</h2>${badge('新秀','green')}</div><div class="custom-score"><div><small>当前能力 CA</small><strong id="customCA">${customCA().toFixed(1)}</strong></div><div><small>潜力 PA</small><strong id="customPA">${customData().potential_hidden}</strong></div></div><p class="muted">保留全部100名真实球员；你作为第101名球员加入世界巡回赛，从零积分开始。能力高低不影响初始排名规则。</p><p id="customWarning" class="help">无总点数限制 · 从零积分开始</p><button class="primary" data-act onclick="startCustomCareer()">开启职业生涯 →</button><p class="help">可将所有能力设为99；属性范围沿用引擎35–99，潜力不低于CA。创建生涯后正常成长、衰退及伤病规则仍生效。</p>`}
function startCustomCareer(){if(busy)return;let d=customData(),ca=customCA();if(!d.name.trim()||d.name.trim().length>40)return toast('请输入1–40字符的球员姓名',true);if(!Number.isInteger(d.age)||d.age<16||d.age>40||!Number.isInteger(d.height_cm)||d.height_cm<140||d.height_cm>200)return toast('年龄或身高超出范围',true);if(Object.values(d.attributes).some(v=>!Number.isFinite(v)||v<35||v>99)||!Number.isFinite(d.potential_hidden)||d.potential_hidden+1e-7<ca||d.potential_hidden>99||d.potential_hidden<35)return toast('请检查属性范围与潜力',true);act('new',{custom:JSON.parse(JSON.stringify(d)),seed:crypto.getRandomValues(new Uint32Array(1))[0]},'自建球员生涯已启动')}

function pickerRows(){let list=(S?S.players:preview).filter(x=>(x.name+' '+(x.zh||'')+' '+x.country+' '+(countries[x.country]||'')).toLowerCase().includes(setupSearch.toLowerCase())).sort((a,b)=>a.rank-b.rank);return `<table><thead><tr><th>选择</th><th>排名</th><th>球员</th><th>年龄</th><th>CA</th><th>PA 预估</th><th>技术风格</th></tr></thead><tbody>${list.map(x=>`<tr class="${selected.includes(x.id)?'ownrow':''}"><td><input type="radio" name="careerPlayer" aria-label="扮演 ${full(x)}" ${selected.includes(x.id)?'checked':''} onchange="togglePick(${x.id},this.checked)"></td><td>${x.rank}</td><td><button class="link" onclick="profile(${x.id})">${full(x)}</button><div class="mini">${esc(x.country)} · ${esc(x.name)}</div></td><td>${x.age}${x.birthdate_source?.startsWith('simulated')?'*':''}</td><td><strong class="caText">${dec(x.ability)}</strong></td><td><strong class="paText">${paLabel(x)}</strong></td><td>${style(x)}</td></tr>`).join('')}</tbody></table>${list.length?'':'<div class="empty">没有匹配的球员</div>'}`}
function chosen(){let x=p(selected[0]);return `<div class="row between"><h2>生涯球员</h2>${badge(x?'已选择':'请选择','green')}</div><p class="muted">选择一名女单球员，体验她从当前阶段到退役的完整职业生涯。新赛季延续同一身份。</p>${x?`<div class="chosen row between"><div><strong>${full(x)}</strong><p class="mini">${esc(x.country)} · CA ${dec(x.ability)} · PA ${paLabel(x)}</p></div><button class="small" onclick="togglePick(${x.id},false)">取消</button></div>`:'<div class="chosen muted">尚未选择生涯角色</div>'}<button class="primary" data-act onclick="startCareer()" ${!x?'disabled':''}>开启职业生涯 →</button><p class="help">属性与PA均为模拟评分。年龄带 * 表示未核实的模拟年龄。比赛由引擎自动执行，你决定参赛和战术。</p>`}function togglePick(id,v){selected=v?[id]:selected.filter(x=>x!==id);let list=$('pickrows'),y=list.scrollTop;list.innerHTML=pickerRows();list.scrollTop=y;$('chosen').innerHTML=chosen()}function pickSearch(v){setupSearch=v;$('pickrows').innerHTML=pickerRows()}
function setup(){return `<div class="setup"><div class="row between"><div class="logo" style="color:#4c6a5e">SMASH <small>V15.4 / CAREER</small></div><div class="row">${fullscreenButton()}<button onclick="$('savefile').click()">导入生涯存档</button></div></div><section class="setuphero"><div><div class="eyebrow" style="color:#e4e9d9">WOMEN'S SINGLES · 2027</div><h1>从第一分，<br>到世界第一。</h1><p class="muted">扮演一名女单球员，亲自决定参赛与休赛，选择比赛策略，见证自己的逐拍比赛和成长。从第一场巡回赛走向世界第一。</p></div><div class="decoration" style="border:1px solid #a0b1a1;border-radius:17px;padding:21px;display:grid;gap:12px"><div class="metric" style="color:#e4e9d9">100</div><small style="color:#e6eadf">BWF 女单世界排名前100名</small><div class="divider" style="background:#a0b1a1"></div><div class="metric" style="color:#e4e9d9">37</div><small style="color:#e6eadf">2027赛季赛事 · 女子单打</small></div></section><div class="setup-modes" role="group" aria-label="创建生涯方式"><button class="${setupMode==='existing'?'primary':''}" onclick="setSetupMode('existing')">扮演现有球员</button><button class="${setupMode==='custom'?'primary':''}" onclick="setSetupMode('custom')">自建球员</button></div><div class="pickpanel">${setupMode==='custom'?customPanel()+`<div class="card stack" id="chosen">${customChosen()}</div>`:`<div class="card stack"><div class="row between"><h2>选择生涯球员</h2>${badge('2026.11.24 · BWF 女单')}</div><input placeholder="搜索球员 / 国家" value="${esc(setupSearch)}" oninput="pickSearch(this.value)"><div class="tablewrap picklist" id="pickrows">${pickerRows()}</div></div><div class="card stack" id="chosen">${chosen()}</div>`}</div><p class="help">V15.4 · 个人球员生涯 · 技术评分为游戏估计 · 首次启动需要联网</p></div>`}


/* shell */
function render(){if(S&&tab==='match'){watchRender();return}watchKey=null;let oldLog=document.querySelector('.live-feed .log'),oldTrace=document.querySelector('.live-feed .trace'),logTop=oldLog?.scrollTop||0,traceTop=oldTrace?.scrollTop||0;if(!S){$('root').innerHTML=setup();return}let views={home,inbox:inboxPage,players,growth:growthPage,calendar:calendarPage,event:eventPage,match:matchPage,rank:rankPage,history:historyPage};$('root').innerHTML=tab==='match'?`<div class="immersive"><main class="content immersive-content">${matchPage()}</main></div>`:`<div class="shell"><aside class="side"><div class="logo">SMASH <small>V15.4</small></div><div class="mini" style="color:#c8d3c8;margin-top:8px">WOMEN'S SINGLES · PLAYER CAREER</div><div class="nav">${NAV.filter(([k])=>k!=='match'||S.match||S.last).map(([k,i,t])=>`<button class="${(tab===k||k==='calendar'&&tab==='event')?'active':''}" onclick="go('${k}')"><span class="ico">${i}</span>${t}${k==='inbox'&&unreadCount()?`<span class="navcount">${unreadCount()}</span>`:''}${k==='match'&&S.match?' ●':''}</button>`).join('')}</div><div class="sidefoot"><small style="color:#c8d3c8">${storageOK?'已自动保存':'建议手动导出备份'}</small></div></aside><div class="work"><header class="topbar"><div><span class="mobilebrand">SMASH V15.4 · </span><small>${S.career_player_id!=null?nm(S.career_player_id):'历史存档'} · 第 ${S.year-2026} 赛季</small><div class="date">${S.date}</div></div><div class="row">${S.career_ended?button('查看生涯总结',"go('history')",'primary continue-main'):button(S.match?'进入比赛 →':S.closed?'开启下一赛季 →':pendingEntry()?'确认报名 →':'继续生涯 →',"advance(370)",'primary continue-main')}<button onclick="menu()" aria-label="生涯设置及存档">设置 ···</button></div></header><main class="content">${views[tab]()}</main></div></div>`;if(busy)document.querySelectorAll('button[data-act]').forEach(b=>b.disabled=true);if(tab==='growth'&&growthId!=null)loadGrowth();if(tab==='event')loadEvent();if(tab==='match'){let l=document.querySelector('.live-feed .log'),t=document.querySelector('.live-feed .trace');if(l)l.scrollTop=logTop;if(t)t.scrollTop=traceTop;spatialIdle()}}
function menu(){modal('生涯设置',`<div class="stack"><h3>显示</h3>${fullscreenButton()}<h3>日程</h3>${button('推进一天','closeModal();advance(1)','',S.career_ended)}${button('模拟至本赛季结束','autoSeason()','',S.career_ended)}<h3>存档</h3>${button('导出存档','exportSave()')}${button('导入存档',"$('savefile').click()")}<h3>重新开始</h3>${button('新建生涯','resetCareer()','danger')}<p class="help">自动模拟将按开赛顺序报名，跳过同期冲突赛事并完成比赛，将略过你逐站选择参赛的机会。正式比赛均为15分制。</p></div>`)}


/* home */
function playerCard(x){let f=x.fitness,st=x.season_stats;return `<div class="card playercard compact-player"><div class="row"><div class="avatar">${esc(x.country)}</div><div style="flex:1;min-width:0"><button class="link pname" onclick="profile(${x.id})">${full(x)}</button><small>世界第 ${x.rank} · ${x.age} 岁</small></div>${badge(x.retired_date?'已退役':f.injury_penalty?'伤病':'健康',x.retired_date||f.injury_penalty?'orange':'green')}</div>${ratingPair(x)}<div class="player-quick"><div><small>赛季战绩</small><b>${st.wins}–${st.losses}</b></div><div><small>疲劳</small><b>${dec(f.fatigue)}</b></div><div><small>状态</small><b>${f.form>=0?'+':''}${dec(f.form)}</b></div></div><div class="row between"><button class="link" onclick="profile(${x.id})">球员档案</button><button class="link" onclick="openGrowth(${x.id})">成长轨迹 ↗</button></div></div>`}
function pendingEntry(){return S.calendar.find(e=>e.phase==='open'&&e.controlled.some(i=>!(String(i) in e.intents))&&e.deadlines.close<=S.date)}function nextEvent(){return S.calendar.find(e=>e.status==='scheduled'&&e.end>=S.date)}function home(){let roster=S.career_player_id!=null?[p(S.career_player_id)].filter(Boolean):[],wins=roster.reduce((a,x)=>a+x.season_stats.wins,0),done=S.calendar.filter(e=>e.status==='completed'||e.status==='cancelled').length,pend=pendingEntry(),open=S.calendar.filter(e=>e.phase==='open'&&e.controlled.some(i=>!(String(i) in e.intents))),e=S.calendar.find(x=>x.status==='scheduled'&&x.start>S.date),m=S.match,task=S.career_ended?{k:'生涯已结束',title:roster.length?'退役档案':'旧观察者存档',sub:'保留全部历史，可查看总结或新建生涯',action:'生涯总结 →',js:"go('history')"}:m?{k:'待赛 · '+matchStage(m),title:nm(m.a)+'  vs  '+nm(m.b),sub:esc(ev(m.event_id)?.name||m.event_id),action:'进入比赛 →',js:'enterLive()'}:pend?{k:'本站报名',title:esc(pend.name),sub:'决定本站参赛或休赛',action:'确认报名 →',js:`entry('${pend.id}')`}:S.closed?{k:'赛季结束',title:'开启新的赛季',sub:'继续职业生涯，迎接新的赛季',action:'开启下一赛季 →',js:'advance(370)'}:open.length?{k:'报名待办 · '+open.length+' 站',title:esc(open[0].name),sub:'截止 '+open[0].deadlines.close,action:'查看报名 →',js:`entry('${open[0].id}')`}: {k:'下一站',title:e?esc(e.name):'本季日程',sub:e?e.start+' — '+e.end:'继续推进日程',action:'继续生涯 →',js:'advance(370)'};return `<div class="home-title"><div><div class="eyebrow">SEASON ${S.year}</div><h1>生涯主页</h1><small>${roster.length?full(roster[0])+' · '+(roster[0].retired_date?'已退役':'职业生涯'):'历史存档'}</small></div><div class="home-season"><span>赛季进度 <b>${done} / ${S.calendar.length}</b></span><span>生涯胜场 <b>${wins}</b></span></div></div>${S.career_migration?.previous_roster?.length>1?`<div class="callout">旧版多人存档已转换为个人生涯：${nm(S.career_player_id)}。原赛果保留，其他球员恢复自动模拟。</div>`:''}<section class="card focus-card"><div><div class="eyebrow">${task.k}</div><h2>${task.title}</h2><p class="muted">${task.sub}</p></div>${button(task.action,task.js,'primary')}</section><div class="row between"><h2>竞技状态</h2>${button('球员数据库',"go('players')",'small')}</div>${roster.length?`<div class="grid">${roster.map(playerCard).join('')}</div>`:'<div class="card empty">此旧存档没有个人生涯身份。请新建生涯。</div>'}<div class="card stack"><div class="row between"><h2>最近赛果</h2>${S.match||S.last?'<button class="link" onclick="go(\'match\')">比赛中心 →</button>':''}</div>${resultsTable(S.recent.slice(0,5))}</div>${S.news.length?`<details class="card compact-details"><summary>世界动态 · ${S.news.length} 条</summary>${S.news.slice(0,4).map(newsLine).join('')}<button class="link" onclick="go('history')">历史档案 →</button></details>`:''}` }
function newsLine(x){return `<div class="newsline"><span class="dot ${x.type==='retirement'?'ret':''}"></span><div><small>${esc(x.date)} · ${x.type==='retirement'?'退役':'青年出道'}</small><div><button class="link" onclick="profile(${x.id})">${nm(x.id)}</button> ${x.age} 岁 · CA ${dec(x.CA)}</div></div></div>`}


/* players */
function players(){return page('球员档案','查看对手的技术画像、年龄、竞技状态与职业生涯记录。')+`<div class="card stack"><div class="toolbar"><input id="psearch" placeholder="搜索姓名 / 国家" value="${esc(search)}" oninput="search=this.value;refreshRows()"><select onchange="rankFilter=this.value;refreshRows()"><option value="all" ${rankFilter==='all'?'selected':''}>全部现役</option><option value="own" ${rankFilter==='own'?'selected':''}>本人</option><option value="youth" ${rankFilter==='youth'?'selected':''}>新生代</option><option value="retired" ${rankFilter==='retired'?'selected':''}>已退役</option></select><select onchange="rankSort=this.value;refreshRows()"><option value="rank" ${rankSort==='rank'?'selected':''}>世界排名</option><option value="ability" ${rankSort==='ability'?'selected':''}>当前能力</option><option value="potential" ${rankSort==='potential'?'selected':''}>潜力 PA</option><option value="age" ${rankSort==='age'?'selected':''}>年龄</option><option value="race" ${rankSort==='race'?'selected':''}>年度积分</option></select></div><div id="rows" class="tablewrap">${playerRows()}</div></div>`}function rankPage(){return page('世界排名','滚动52周最佳10站；年度总决赛积分采用最佳14站（S100最多3站）；总决赛前两周内赛事积分计入下一届。')+`<div class="card stack"><div class="toolbar"><input placeholder="搜索球员 / 国家" value="${esc(search)}" oninput="search=this.value;refreshRows()"><select onchange="rankSort=this.value;refreshRows()"><option value="rank" ${rankSort==='rank'?'selected':''}>世界排名</option><option value="race" ${rankSort==='race'?'selected':''}>年度巡回赛积分</option><option value="ability" ${rankSort==='ability'?'selected':''}>CA排序</option><option value="potential" ${rankSort==='potential'?'selected':''}>PA排序</option></select></div><div id="rows" class="tablewrap">${playerRows(true)}</div><p class="help">初始积分为游戏参考基准，按模拟账本逐步到期，不代表真实历史逐站成绩。</p></div>`}
function refreshRows(){$('rows').innerHTML=playerRows(tab==='rank')}function playerRows(ranking=false){let list=(ranking||rankFilter!=='retired'?S.players:S.retired).filter(x=>(ranking||rankFilter==='all'||rankFilter==='retired'||rankFilter==='own'&&isOwn(x.id)||rankFilter==='youth'&&x.origin==='fictional_youth')&&(x.name+' '+(x.zh||'')+' '+x.country+' '+(countries[x.country]||'')).toLowerCase().includes(search.toLowerCase()));list.sort((a,b)=>rankSort==='potential'?paMid(b)-paMid(a):rankSort==='ability'?b.ability-a.ability:rankSort==='age'?a.age-b.age:rankSort==='race'?b.race_points-a.race_points:a.rank-b.rank);return `<table><thead><tr><th>排名</th><th>球员</th><th>协会</th><th>年龄</th><th>CA</th><th>PA 预估</th><th>世界积分</th><th>年度积分</th><th>赛季战绩</th><th>冠军</th></tr></thead><tbody>${list.map(x=>`<tr class="${isOwn(x.id)?'ownrow':''}"><td class="ranknum">${x.retired_date?'—':x.rank}</td><td><button class="link" onclick="profile(${x.id})">${full(x)}</button> ${isOwn(x.id)?badge('本人','green'):x.origin==='fictional_youth'?badge('新秀'):''}<div class="mini">${style(x)}</div></td><td>${esc(x.country)}</td><td>${x.age}${x.birthdate_source?.startsWith('simulated')?'*':''}</td><td><strong class="caText">${dec(x.ability)}</strong></td><td><strong class="paText">${paLabel(x)}</strong></td><td>${fmt(x.points)}</td><td>${fmt(x.race_points)}</td><td>${x.season_stats.wins}–${x.season_stats.losses}</td><td>${x.season_stats.titles}</td></tr>`).join('')}</tbody></table>${list.length?'':'<div class="empty">没有匹配的球员</div>'}`}
function closeProfile(){$('profileLayer').innerHTML=''}
function ratingClass(v){return v>=95?'elite':v>=90?'high':v>=80?'good':v>=70?'mid':'low'}
function profile(id){let x=p(id);if(!x)return;let c=x.career_stats||{},f=x.fitness||{},st=x.season_stats||{},attrs=Object.entries(x.attributes),groups=[['技术能力','TECHNICAL',attrs.slice(0,7)],['身体能力','PHYSICAL',attrs.slice(7,12)],['心理与决策','MENTAL',attrs.slice(12)]];let pick=!!$('pickrows')&&(!S||!!$('modal').querySelector('#pickrows'));let top=attrs.slice().sort((a,b)=>b[1]-a[1]).slice(0,3);let low=attrs.slice().sort((a,b)=>a[1]-b[1]).slice(0,2);$('profileLayer').innerHTML=`<div class="modalback profileback" onclick="if(event.target===this)closeProfile()"><section class="profilemodal" role="dialog" aria-modal="true" aria-label="球员档案"><div class="profiletop row between"><span class="eyebrow">球员档案 / PLAYER REPORT</span><button onclick="closeProfile()" aria-label="关闭球员档案">${pick?'← 返回选人':'✕ 关闭'}</button></div><div class="profilehero"><div class="profileidentity"><div class="profileavatar"><span>${esc(x.country)}</span><small>WS</small></div><div><div class="tagrow">${badge(countries[x.country]||x.country)}${badge(style(x))}${isOwn(id)?badge('本人','green'):''}${x.retired_date?badge('已退役','orange'):''}</div><h1>${full(x)}</h1><p class="muted">${esc(x.name)} · ${x.age} 岁 · 女单 · ${esc(x.career_birthdate||'出生日期未知')}（${x.age_verified?'公开出生日期':'模拟生日'}）</p><p class="help">${x.age_verified?'出生日期有公开来源':'年龄为未核实游戏设定'} · ${x.profile_basis==='results_rating_prior'?'结果评级先验':x.profile_basis==='ws_rank_prior'||x.profile_basis==='rank_prior'?'排名先验':x.profile_basis==='match_sample'?'交战样本 '+x.history_sample_count+' 场':'游戏生涯数据'} · 属性为模拟评分</p><p class="mini">身高 ${x.height_cm?esc(x.height_cm)+' cm':'未核实'} · 持拍 ${x.handedness==='left'?'左手':x.handedness==='right'?'右手':'未核实'}${x.external_rating?' · 初始参考评级 '+esc(x.external_rating.value)+'（'+esc(x.external_rating.date)+'）':''}</p>${String(x.profile_sources?.biography||'').startsWith('https://')?`<p class="mini"><a href="${esc(x.profile_sources.biography)}" target="_blank" rel="noopener noreferrer">公开档案来源</a></p>`:''}</div></div>${ratingPair(x)}</div><div class="profilekpis">${[['世界排名',x.retired_date?'已退役':'#'+x.rank],['世界积分',fmt(x.points)],['赛季胜率',pct(st.wins,st.wins+st.losses)],['赛季冠军',st.titles||0],['生涯最佳排名',c.best_rank||'—']].map(([k,v])=>`<div><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><div class="profilecontent"><div class="profileattrs"><div class="row between"><h2>球员属性</h2><div class="attrlegend"><span class="elite">95+</span><span class="high">90–94</span><span class="good">80–89</span><span class="mid">70–79</span><span class="low">70以下</span></div></div><div class="attrgrid">${groups.map(([n,en,arr])=>`<div class="attrgroup"><header><h3>${n}</h3><small>${en}</small></header>${arr.map(([k,v])=>`<div class="fmattr"><span>${esc(k)}</span><b class="${ratingClass(v)}">${dec(v)}</b></div>`).join('')}</div>`).join('')}</div></div><div class="profileaside"><div class="card"><h3>竞技状态</h3><div class="divider"></div>${[['竞技状态',f.form],['综合疲劳',f.fatigue],['残余疲劳',f.residual],['长期负荷',f.chronic],['伤病影响',f.injury_penalty]].map(([k,v])=>`<div class="row between condition"><small>${k}</small><strong>${dec(v)}</strong></div>`).join('')}</div><div class="card"><h3>生涯统计</h3><div class="divider"></div><div class="condition row between"><small>赛季战绩</small><strong>${st.wins||0}–${st.losses||0}</strong></div><div class="condition row between"><small>已归档冠军</small><strong>${c.titles||0}</strong></div><div class="condition row between"><small>峰值 CA</small><strong>${dec(c.peak_CA)}</strong></div><div class="condition row between"><small>完成赛季</small><strong>${c.seasons||0}</strong></div></div></div></div>${S&&!pick?`<section class="profile-analytics"><h2>生涯技术与空间统计</h2><div id="profileAnalytics"><p class="coach-note">正在读取历史统计…</p></div></section>`:''}<div class="profilefoot row between"><small>CA为派生综合评分；PA为潜力预估区间，不是保证达到的上限。</small>${S&&!pick?button('查看成长轨迹 ↗',`openGrowth(${id})`,'primary'): ''}${pick?`<button class="primary"  onclick="togglePick(${id},${!selected.includes(id)});closeProfile()">${selected.includes(id)?'取消选择':'选择该球员'}</button>`:''}</div></section></div>`;if(S&&!pick)loadProfileAnalytics(id)}


/* inbox */
function unreadCount(){let read=new Set(S?.inbox_read||[]);return (S?.inbox||[]).filter(x=>!read.has(x.id)).length}
function mailLabel(x){return ({direct:'直接入围',qualifying:'进入资格赛',qualified:'晋级正赛',qualifying_eliminated:'资格赛淘汰',rejected:'未入围'})[x.entry_status]||(x.admitted?'正式入围':'未入围')}let mailId=null,mailFilter='all';
function inboxPage(){let messages=S.inbox||[],read=new Set(S.inbox_read||[]),visible=messages.filter(x=>mailFilter==='all'||!read.has(x.id)||x.id===mailId);if(!messages.some(x=>x.id===mailId))mailId=messages.find(x=>!read.has(x.id))?.id??(mailFilter==='all'?messages[0]?.id:null)??null;let active=messages.find(x=>x.id===mailId);return page('消息中心','赛事通知与报名结果',button('全部标为已读',"markAllMail()",'',!unreadCount()))+`<section class="card maildesk"><aside class="mail-list-pane"><header class="mail-pane-head"><div><h2>收件箱</h2><small>${messages.length} 条消息 · ${unreadCount()} 条未读</small></div><div class="sectiontabs mail-tabs"><button class="small ${mailFilter==='all'?'active':''}" onclick="filterMail('all')">全部</button><button class="small ${mailFilter==='unread'?'active':''}" onclick="filterMail('unread')">未读</button></div></header><div class="mail-list" id="mailList">${visible.map(x=>`<button class="mail-item ${x.id===mailId?'selected':''} ${read.has(x.id)?'':'unread'}" data-mail="${esc(x.id)}" onclick="selectMail(this.dataset.mail)"><span class="mail-indicator"></span><span class="mail-summary"><span class="mail-title">${esc(x.event_name)}</span><span class="mail-subject">${nm(x.player_id)} · ${mailLabel(x)}</span><small>${esc(x.date)}</small></span></button>`).join('')||'<div class="empty">暂无消息</div>'}</div></aside><article class="mail-reading" id="mailReading">${active?`<div class="mail-reading-head"><div class="row">${badge(mailLabel(active),active.entry_status==='qualifying'?'blue':active.admitted?'green':'orange')}<small>${esc(active.date)}</small></div><h1>${esc(active.event_name)}</h1><div class="row"><span class="avatar mail-avatar">${esc(p(active.player_id)?.country||'MS')}</span><div><button class="link" onclick="profile(${Number(active.player_id)})">${nm(active.player_id)}</button><div class="muted">赛事组委会 · ${mailLabel(active)}</div></div></div></div><div class="mail-copy"><p>${esc(active.reason)}</p></div><div class="row mail-actions">${button('查看赛事 →',`eventDetails('${esc(active.event)}')`,'primary')}${!read.has(active.id)?`<button data-mail="${esc(active.id)}" onclick="selectMail(this.dataset.mail)">标为已读</button>`:''}</div>`:'<div class="empty"><h2>暂无赛事通知</h2><p>报名审核和资格赛结果将在这里显示。</p></div>'}</article></section>`}
function filterMail(k){mailFilter=k;mailId=null;render()}
function refreshMail(){if(tab!=='inbox')return;let scroll=$('mailList')?.scrollTop||0;let main=document.querySelector('.content');if(main)main.innerHTML=inboxPage();if($('mailList'))$('mailList').scrollTop=scroll;let nav=[...document.querySelectorAll('.nav button')].find(b=>b.getAttribute('onclick')==="go('inbox')");if(nav){nav.querySelector('.navcount')?.remove();if(unreadCount())nav.insertAdjacentHTML('beforeend',`<span class="navcount">${unreadCount()}</span>`);}}
function markMail(ids){if(!S||busy)return;let old=new Set(S.inbox_read||[]),add=ids.filter(i=>!old.has(i));if(!add.length)return;S.inbox_read=[...new Set([...old,...add])];let state=S; // immediately update display; worker only receives message IDs
rpc('read_inbox',{ids:add}).then(j=>{if(j.error)throw Error(j.error)}).catch(e=>{if(S===state)toast('已读状态同步失败：'+e.message,true)});
if(db)storeMailRead(S.inbox_read).catch(()=>{storageOK=false;toast('已读状态本地保存失败，请导出存档备份',true)});}
function selectMail(id){if(busy||!S||!S.inbox.some(x=>x.id===id))return;mailId=id;markMail([id]);refreshMail()}
function markAllMail(){if(busy)return;markMail(S.inbox.map(x=>x.id));refreshMail()}


/* calendar */
function ownEntryStatus(e,i){let k=String(i),r=e.decisions?.[k];if(e.team_conflicts?.length&&e.phase==='not_open')return ['同期互斥','orange'];if(e.withdrawn?.[k])return ['已退赛','orange'];if(e.phase==='cancelled')return ['赛事取消','orange'];if(e.phase==='open')return e.intents[k]===true?['已报名','green']:e.intents[k]===false?['休赛','']:e.controlled.includes(i)?['待确认','orange']:['协会管理',''];if(e.phase==='not_open')return ['未开放',''];let q=e.qualification||{};if(q.eliminated?.[k])return [stage(q.eliminated[k])+'淘汰','orange'];let z=e.sporting_status?.[k];if(z?.state==='group_pending')return [`${z.group}组 · ${z.played}/${z.required}场`,'blue'];if(z?.state==='group_wait')return [`${z.group}组 · 等待晋级结果`,'blue'];if(z?.state==='group_eliminated')return [`${z.group}组 · 小组出局`,'orange'];if(z?.state==='group_qualified')return [`${z.group}组 · 已晋级`,'green'];if(z?.state==='placement')return [(e.level==='FINALS'&&e.ruleset==='bwf84'?['冠军','亚军','四强','八强','小组第三','小组第四']:['冠军','亚军','四强','八强','十六强','32强/小组出局','64强/小组出局','资格赛出局'])[z.placement]||'已完赛',z.placement<=1?'green':''];if(z?.state==='eliminated')return [stage(z.stage)+'淘汰','orange'];if(z?.state==='champion')return ['冠军','green'];if(z?.state==='pending')return [stage(z.stage)+'待赛','blue'];if(z?.state==='advanced')return [stage(z.stage)+'获胜','green'];if(q.winners?.includes(i))return ['资格赛晋级','green'];if(q.entrants?.includes(i))return [e.phase==='accepted'?'资格赛名单':'资格赛','blue'];if(e.accepted.includes(i))return [e.phase==='accepted'?'正赛名单':'直接入围','green'];if(e.phase==='accepted'&&e.reserves.includes(i))return ['候补 '+(e.reserves.indexOf(i)+1),'orange'];if(e.intents[k]===false)return ['休赛',''];if(e.intents[k]===true||r?.willing)return ['未入围','orange'];return ['未报名','']}
function calendarSummary(){let urgent=pendingEntry(),due=urgent||S.calendar.find(e=>e.phase==='open'&&e.controlled.some(i=>!(String(i) in e.intents))),pendingCount=S.calendar.filter(e=>e.phase==='open'&&e.controlled.some(i=>!(String(i) in e.intents))).length,active=S.calendar.filter(e=>e.status==='scheduled'&&e.start<=S.date&&e.end>=S.date),next=S.calendar.find(e=>e.status==='scheduled'&&e.start>S.date);return `<div class="scheduleband"><div><small>当前赛事</small><strong>${active.length?active.map(e=>esc(e.name)).join(' / '):'休赛 / 赛间准备'}</strong></div><div><small>下一站</small><strong>${next?esc(next.name):'本季已无后续赛事'}</strong><small>${next?next.start:''}</small></div><div><small>报名待办</small><strong>${due?esc(due.name):'暂无必须处理事项'}</strong>${due?`<small>${urgent?'本站报名日':'截止 '+due.deadlines.close} · 共 ${pendingCount} 站待确认</small>`+button(urgent?'立即确认':'确认报名',`entry('${due.id}')`,'primary small'):''}</div></div>`}
function calendarPage(){return page('赛事','选择参赛与休赛，查看个人赛历、签表与赛果。',S.match?button('进入比赛 →','enterLive()','primary'):'')+`<div class="card stack"><div class="toolbar"><select onchange="calFilter=this.value;calendarRows()"><option value="upcoming" ${calFilter==='upcoming'?'selected':''}>未结束赛事</option><option value="all" ${calFilter==='all'?'selected':''}>全年赛事</option><option value="open" ${calFilter==='open'?'selected':''}>可报名</option><option value="done" ${calFilter==='done'?'selected':''}>已结束</option></select><select onchange="calLevel=this.value;calendarRows()"><option value="all">全部级别</option>${['1000','750','500','300','100','WC','FINALS'].map(l=>`<option value="${l}" ${calLevel===l?'selected':''}>${l==='WC'?'世锦赛':l==='FINALS'?'总决赛':'S'+l}</option>`).join('')}</select><small>${S.year} 年 · ${S.calendar_policy==='bwf80'&&S.year<=2028?'BWF 官方赛历':'模拟赛历'}</small></div><details class="source-note compact-details"><summary>赛历来源与报名规则</summary>${S.calendar_policy==='bwf80'?`2027–2028 巡回赛日期依据 <a href="https://res.cloudinary.com/badminton/images/v1782784055/wordpress_assets_test/BWF-World-Tour-Calendar-2027-2028/BWF-World-Tour-Calendar-2027-2028.pdf" target="_blank" rel="noopener">BWF 公布赛历</a>；2027世锦赛为7月14–25日加拿大密西沙加，2029年起采用模拟赛历。2027已公布规则优先；S100正赛48人，S300/S500正赛32人，S750正赛32人，S1000/世锦赛48人小组赛，总决赛8人。本游戏采用逐站报名；同期赛事你只能参加一站，跳过较早开赛的赛事即可等待另一站。`:'旧存档保留原赛季日期与已确认报名；下赛季切换新版赛历。'}</details><div id="eventrows">${eventRows()}</div></div>`}function calendarRows(){$('eventrows').innerHTML=eventRows()}function eventRows(){let es=S.calendar.filter(e=>(calLevel==='all'||e.level===calLevel)&&(calFilter==='all'||calFilter==='upcoming'&&e.status==='scheduled'||calFilter==='open'&&e.phase==='open'||calFilter==='done'&&e.status!=='scheduled'));let month='';return es.map(e=>{let group=e.start.slice(0,7),head=group!==month?`<div class="month">${group.slice(0,4)} 年 ${+group.slice(5)} 月</div>`:'';month=group;let mine=e.accepted.filter(isOwn),wait=e.reserves.filter(isOwn);return head+`<div class="eventrow"><div class="dateblock">${e.start.slice(5)}<br><small>至 ${e.end.slice(5)}</small></div><div><div class="row">${lvl(e.level)}<strong>${esc(e.name)}</strong>${e.calendar_confirmed===false?badge(e.level==='WC'?'游戏日期':'模拟日期','orange'):''}</div><div class="calendar-meta"><small>${esc(e.city||'')}</small><small>${e.phase==='not_open'?(e.team_conflicts?.length?'同期已锁定':'开赛日 '+e.deadlines.open.slice(5)):e.phase==='open'?'本站确认 '+e.deadlines.close.slice(5):'抽签 '+e.deadlines.draw.slice(5)}</small></div>${e.overlaps?.length?`<div class="conflict-note">同期：${e.overlaps.map(esc).join('、')}${e.team_conflicts?.length?' · 已选择 '+e.team_conflicts.map(esc).join('、'):' · 只选一站'}</div>`:''}</div><div class="eventstatus">${badge(e.phase==='open'&&e.controlled.length&&e.controlled.every(i=>String(i) in e.intents)?'报名已确认':e.phase==='drawn'&&e.start<=S.date&&e.end>=S.date?'比赛进行中':status(e),e.phase==='open'?'orange':e.status==='completed'?'green':'')}<div class="mini">${e.champion?'冠军 '+nm(e.champion):e.played?`${e.played} / ${e.total} 场`:''}</div><div class="entrytags">${(e.phase==='not_open'?[]:S.roster).map(i=>{let [t,c]=ownEntryStatus(e,i);return `<span>${nm(i)} ${badge(t,c)}</span>`}).join('')}</div></div><div class="row eventaction">${e.phase==='open'&&e.controlled.length?button(e.controlled.every(i=>String(i) in e.intents)?'修改报名':'确认报名',`entry('${e.id}')`,'primary small'):''}${button('查看赛事 →',`eventDetails('${e.id}')`,'small')}</div></div>`}).join('')||'<div class="empty">没有符合条件的赛事</div>'}
function entry(id){let e=ev(id);if(!e||e.phase!=='open'||e.team_conflicts?.length)return;modal('赛事报名 · '+e.name,`<div class="row">${lvl(e.level)}<span class="muted">${e.start} — ${e.end}</span></div><div class="callout" style="margin:12px 0">本站开赛日 ${e.start}。确认后继续日程，当日按最新排名审核并抽签。你可以决定本站参赛或休赛；资格赛自动衔接正赛。</div>${e.overlaps?.length?`<div class="callout warn">同期赛事：${e.overlaps.map(esc).join('、')}。你只能参加一站。若想参加另一站，请先选择本站休赛，等该站开赛时再报名。</div>`:''}${['100','300','500'].includes(e.level)?`<div class="qualnote"><strong>资格赛安排</strong><p>${e.level==='100'?(e.ruleset==='bwf84'?'40个直接入围名额 + 8个资格赛晋级名额（最多32名资格赛选手），正赛使用64签位':'24个直接入围名额 + 8个资格赛晋级名额（旧版赛季）'):'28个直接入围名额 + 4个资格赛晋级名额（最多16名资格赛选手）'}。若有效报名不超过${e.level==='100'&&e.ruleset==='bwf84'?48:32}人则直接进入正赛。资格赛首日进行；S100资格赛晋级球员次日进行正赛首轮。</p></div>`:''}${S.roster.length?S.roster.map(i=>{let x=p(i),control=e.controlled.includes(i),blocked=e.conflicts?.[String(i)]||[],checked=!blocked.length&&(e.intents[String(i)]??(x.fitness.injury_penalty<5));return `<label class="card row" style="margin:9px 0;padding:12px"><input class="entrycheck" type="checkbox" value="${i}" ${checked?'checked':''} ${control&&!blocked.length?'':'disabled'}><div><strong>${full(x)}</strong><div class="muted">排名 ${x.rank} · 疲劳 ${dec(x.fitness.fatigue)} · ${blocked.length?'赛程冲突：已入围 '+blocked.map(esc).join('、'):control?(x.fitness.injury_penalty>=5?'严重伤病':'可报名'):'不可报名'}</div></div></label>`}).join(''):'<p class="muted">生涯已结束，无需报名。</p>'}<div class="row" style="margin-top:15px">${button('确认本站报名',`submitEntry('${id}')`,'primary')}${button('本站休赛',`submitEntry('${id}',true)`,'',!e.controlled.length)}<button onclick="closeModal()">取消</button></div>`)}function submitEntry(id,none=false){let ids=none?[]:[...document.querySelectorAll('.entrycheck:checked:not(:disabled)')].map(x=>+x.value);act('entry',{event:id,ids},'本站报名已确认')}
function resultsTable(rows){return rows.length?`<div class="tablewrap"><table><thead><tr><th>日期 / 轮次</th><th>对阵</th><th>局分</th><th>结果</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.date||'')} · ${matchStage(r)}</td><td>${nm(r.a)} vs ${nm(r.b)}</td><td>${(r.history||[]).map(g=>g.join(':')).join(' / ')||'—'}</td><td>${r.winner?`<strong style="color:var(--green)">${nm(r.winner)}</strong>`:'—'} ${r.outcome&&r.outcome!=='played'?badge(outcomes[r.outcome]||r.outcome):''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">暂无赛果</div>'}
function entryNames(ids){return (ids||[]).map(i=>`<button class="small ${isOwn(i)?'primary':''}" onclick="profile(${i})">${nm(i)}</button>`).join('')||'<small>暂无球员</small>'}
function qualificationPanel(q,d=eventDetail){let gs=q.groups||[],el=q.eliminated||{};return `<div class="qualpanel"><div class="row between"><h3>资格赛通道</h3>${badge(q.finished?'已完成':'待进行','blue')}</div><div class="qualcounts"><div><small>直接入围</small><b>${q.direct.length}</b></div><div><small>资格赛选手</small><b>${q.entrants.length}</b></div><div><small>已晋级正赛</small><b>${q.winners.length}</b></div></div><h3>直接入围正赛</h3><div class="tagrow">${entryNames(q.direct)}</div><h3>资格赛分组签表</h3>${gs.length?`<div class="qualgroups">${gs.map((g,i)=>`<div class="qualgroup"><small>晋级通道 ${i+1} · 1人晋级</small>${g.map(id=>`<div class="row between"><button class="link" onclick="profile(${id})">${nm(id)}${seedMark(d,id,true)}</button>${q.winners.includes(id)?badge('晋级','green'):el[String(id)]?badge('淘汰','orange'):badge('待赛','blue')}</div>`).join('')}</div>`).join('')}</div>`:`<div class="tagrow">${entryNames(q.entrants)}</div>`}<h3>资格赛晋级名单</h3><div class="tagrow">${entryNames(q.winners)}</div>${q.finished?`<h3>正赛最终名单 · ${q.main_entries.length}人</h3><div class="tagrow">${entryNames(q.main_entries)}</div>`:`<p class="muted">${d?.draw_policy==='protected83'?'正赛签位已经预抽，资格赛胜者按通道填入，不重新抽签。':'资格赛结束后生成正赛签表，无需再次报名。'}</p>`}</div>`}
