function personalHistory(){let x=p(S.career_player_id);if(!x)return '';let c=x.career_stats||{},st=x.season_stats||{},rows=S.years.filter(y=>y.personal).slice().reverse();return `<section class="card stack"><div class="row between"><h2>职业生涯 · ${full(x)}</h2>${badge(x.retired_date?'已退役':'现役','green')}</div><div class="metrics">${[['最佳排名',c.best_rank?'#'+c.best_rank:'—'],['峰值 CA',dec(c.peak_CA)],['生涯冠军',(c.titles||0)+(S.closed||x.retired_date?0:st.titles||0)],['完成赛季',c.seasons||0]].map(([k,v])=>`<div><small>${k}</small><div class="metric">${v}</div></div>`).join('')}</div>${rows.length?`<div class="tablewrap"><table><thead><tr><th>赛季</th><th>年终排名</th><th>CA</th><th>胜负</th><th>冠军</th></tr></thead><tbody>${rows.map(y=>`<tr><td>${y.year}</td><td>#${y.personal.rank}</td><td>${dec(y.personal.ability)}</td><td>${y.personal.season_stats.wins}–${y.personal.season_stats.losses}</td><td>${y.personal.season_stats.titles}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">首个赛季完成后记录年终成绩。</p>'}</section>`}
