/* roster */
function startCareer(){if(busy||selected.length!==1)return;act('new',{ids:selected.slice(),seed:crypto.getRandomValues(new Uint32Array(1))[0],profile:'scouting'},'职业生涯已启动')}


/* career-actions */
function addDays(d,n){let x=new Date(d+'T00:00:00Z');x.setUTCDate(x.getUTCDate()+n);return x.toISOString().slice(0,10)}function advance(n){if(busy||S.career_ended)return;if(spatialVisual){stopAuto();spatialVisual=null;spatialPaused=false;}if(S.match){enterLive();return}if(pendingEntry()){entry(pendingEntry().id);return}let target=S.closed?addDays(S.date,1):n===370?`${S.year}-12-31`:addDays(S.date,n);if(!S.closed&&target>`${S.year}-12-31`)target=`${S.year}-12-31`;act('run',{target,auto:false},'日程已推进')}function autoSeason(){if(busy||S.career_ended)return;if(!confirm('确认逐站自动报名并快速模拟至赛季结束？尚未开始的生涯比赛也采用简化属性引擎，不生成空间回放；已开始的比赛保留原引擎。'))return;stopAuto();act('run',{target:`${S.year}-12-31`,auto:true,fast_auto:true},'本赛季自动模拟完成')}
function nextAfterMatch(){spatialVisual=null;spatialPaused=false;showLast=false;if(S.match){enterLive();return}advance(370)}function play(until){if(busy||!S.match)return;if(until==='point'){requestCareerPoint();return;}stopAuto();spatialVisual=null;spatialPaused=false;let m=S.match;act('play',{event:m.event_id,serial:m.serial,until},'')}function retireMatch(id){if(!S.match||!confirm('确认结束这场比赛并按退赛结算？'))return;stopAuto();spatialVisual=null;act('play',{event:S.match.event_id,serial:S.match.serial,retire_id:id},'已退赛')}function stopAuto(){auto=false;autoToken++;clearTimeout(spatialTimer)}function toggleAuto(){if(auto){stopAuto();if(spatialVisual)spatialPaused=true;render();return;}if(!S.match||busy)return;auto=true;spatialPaused=false;spatialLastTick=0;render();if(!spatialVisual)requestCareerPoint();else warmNextPoint()}


/* rpc */
function rpc(action,data={},files=null){return new Promise((resolve,reject)=>{let id=++seq;jobs.set(id,{resolve,reject});worker.postMessage({id,action,data,files})})}async function act(action,data={},msg='',silent=false){if(busy)return;setBusy(true,action==='play'&&data.until==='point'&&auto&&warmKey===S?.match?.event_id+'|'+S?.match?.serial+'|'+S?.match?.log?.length);try{let j=await rpc(action,data.compact&&!storageOK?{...data,compact:false}:data);if(j.error)throw Error(j.error);let beforeMatch=S?.match;let oldChampions=new Set(j.state_patch?[]:(S?.calendar||[]).filter(e=>e.champion).map(championKey));let prevIds=new Set(j.state_patch?[]:(S?.inbox||[]).map(x=>x.id));if(j.state_patch){if(j.append_log)j.state_patch.match.log=[...(beforeMatch?.log||[]),...j.state_patch.match.log];Object.assign(S,j.state_patch)}else{S=j.state;growthCache.clear();eventCache.clear();clearEventDetail();}let newMail=j.state_patch?[]:(S.inbox||[]).filter(x=>!prevIds.has(x.id));if(j.save)lastSave=j.save;let persist=(async()=>{try{if(j.checkpoint_patch)await storePatch(j.checkpoint_patch);else await storeSave(lastSave,['new','restore'].includes(action));storageOK=true}catch{storageOK=false}})();closeModal();lastResult=j.result;if(action==='new'||action==='select'){warmKey='';coachSeen='';coachDialogKey='';coachDraft={};growthId=null;growthSearch='';mailId=null;eventId=null;tab='home';showLast=false}if(action==='restore'){warmKey='';coachSeen='';coachDialogKey='';coachDraft={};growthId=null;growthSearch='';mailId=null;eventId=null;tab='home';showLast=false}if(action==='run'){showLast=false;if(j.result.pause==='match'){selectEvent(j.result.event);eventSection='auto';tab='match'}else if(j.result.pause==='registration'){selectEvent(j.result.event);eventSection='auto';tab='event'}else if(j.result.pause==='registration_result')tab='inbox';else if(j.result.pause==='new_season'){eventId=null;tab='home'}else if(S.closed)tab='history'}if(action==='play'){tab='match';showLast=!!j.result.finished;let after=showLast?S.last:S.match;let r=after?.log?.at(-1)?.spatial;if(spatialRequest&&data.until==='point'&&r&&beforeMatch&&after.event_id===beforeMatch.event_id&&after.serial===beforeMatch.serial)spatialBegin(beforeMatch,r);if(showLast)stopAuto()}if(!j.state_patch&&['play','run'].includes(action)){let won=S.calendar.filter(e=>e.champion&&isOwn(e.champion)&&!oldChampions.has(championKey(e)));if(won.length){let e=won.at(-1),m=S.last?.event_id===e.id&&S.last.stage==='F'?S.last:null;pendingChampion={e,m}}}if(spatialVisual&&action==='play'&&data.until==='point'){render();warmNextPoint();}await persist;setBusy(false);render();if(!spatialVisual){flushChampion();if(action==='play'&&data.until!=='match'&&data.retire_id==null)coachBreak();}if(action!=='play')window.scrollTo(0,0);if(action==='run'&&j.result.pause==='registration'){entry(j.result.event);toast('今日报名截止：请决定本站参赛或休赛')}else if(action==='run'&&j.result.pause==='registration_result'){toast('报名审核完成：未获参赛资格，请查看消息中心',true)}else if(action==='run'&&j.result.pause==='new_season'){toast(S.career_ended?'职业生涯已结束':'新赛季开启，继续生涯')}else if(action==='run'&&j.result.pause==='match')toast(newMail.length?'收到 '+newMail.length+' 条报名结果 · 待进行的生涯比赛':'待进行的生涯比赛');else if(newMail.length&&!silent)toast('收到 '+newMail.length+' 条赛事通知，查看消息中心');else if(msg&&!silent)toast(msg);else if(action==='play'&&j.result.finished&&!spatialVisual)toast('比赛结束');return j}catch(e){stopAuto();toast(e.message,true);setBusy(false);render();return null}finally{setBusy(false)}}


/* storage */
function openDB(){return new Promise((resolve,reject)=>{let q=indexedDB.open('SMASH1092_WS_CAREER',1);q.onupgradeneeded=()=>q.result.createObjectStore('career');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);q.onblocked=()=>reject(Error('存档数据库被占用'))})}function readSave(){return new Promise((resolve,reject)=>{if(!db)return resolve(null);let t=db.transaction('career'),o=t.objectStore('career'),q=o.get('active'),p=o.get('active_patch'),m=o.get('mail_read_patch');t.oncomplete=()=>resolve(q.result?{save:q.result,checkpoint_patch:p.result||null,inbox_read_patch:m.result||[]}:null);t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}function storeSave(v,clearMail=false){return new Promise((resolve,reject)=>{if(!db)return reject(Error('本地存档不可用'));let t=db.transaction('career','readwrite'),o=t.objectStore('career');v==null?o.delete('active'):o.put(v,'active');o.delete('active_patch');if(clearMail||v==null)o.delete('mail_read_patch');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}function storeMailRead(ids){return new Promise((resolve,reject)=>{let t=db.transaction('career','readwrite');t.objectStore('career').put(ids,'mail_read_patch');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}function storePatch(v){return new Promise((resolve,reject)=>{if(!db)return reject(Error('本地存档不可用'));let t=db.transaction('career','readwrite');t.objectStore('career').put(v,'active_patch');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}async function exportSave(){if(busy||!S)return;stopAuto();setBusy(true);try{let read=new Set(S.inbox_read||[]),ids=(S.inbox||[]).filter(x=>read.has(x.id)).map(x=>x.id);if(ids.length){let ack=await rpc('read_inbox',{ids});if(ack.error)throw Error(ack.error)}let j=await rpc('checkpoint');if(j.error)throw Error(j.error);lastSave=j.save;try{await storeSave(lastSave);storageOK=true}catch{storageOK=false}let u=URL.createObjectURL(new Blob([lastSave],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=`SMASH_V15.4-${S.date}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}catch(e){toast(e.message,true)}finally{setBusy(false)}}$('savefile').onchange=async e=>{let f=e.target.files[0];e.target.value='';if(!f||busy)return;if(S&&!confirm('导入会覆盖当前生涯，请确认已备份。'))return;try{await act('restore',{save:await f.text()},'存档已载入');go('home')}catch(e){toast(e.message,true)}};async function resetCareer(){if(busy||!confirm('确定重开？建议先导出存档。'))return;stopAuto();setBusy(true);try{await rpc('reset');try{await storeSave(null)}catch{}S=null;lastSave=null;selected=[];setupSearch='';closeModal();render()}catch(e){toast(e.message,true)}finally{setBusy(false)}}


/* growth */
const growthCache=new Map();let growthId=null,growthPeriod='365',growthRequest=0,growthSearch='';
function paLabel(x){return Array.isArray(x?.potential_estimate)?x.potential_estimate.join('–'):'—'}
function paMid(x){let a=x?.potential_estimate;return Array.isArray(a)?(a[0]+a[1])/2:-1}
function ratingPair(x){return `<div class="ratingpair"><div class="ratingtile caTile"><small>CA · 当前能力</small><strong>${Number(x.ability).toFixed(2)}</strong><span>Current Ability</span></div><div class="ratingtile paTile"><small>PA · 潜力预估</small><strong>${paLabel(x)}</strong><span>Potential Ability</span></div></div>`}
function openGrowth(id){if(!S)return;growthId=id;growthSearch=isOwn(id)?'':(p(id)?.zh||p(id)?.name||'');closeProfile();$('modal').innerHTML='';go('growth',true)}
function growthPage(){if(!p(growthId))growthId=S.career_player_id??null;let x=p(growthId);return page('成长中心','跟踪能力、潜力与单项属性变化。')+`<div class="growthlayout"><div class="card growthlist"><h3>成长对比</h3><input placeholder="搜索其他球员 / 国家" aria-label="搜索球员" value="${esc(growthSearch)}" oninput="growthSearch=this.value;refreshGrowthList()"><div id="growthList">${growthList()}</div></div>${x?`<div class="growthmain"><div class="card growthhero"><div class="row between"><div><div class="eyebrow">PLAYER DEVELOPMENT / ${esc(x.country)}</div><h1>${full(x)}</h1><p class="muted">${x.age} 岁 · ${style(x)} · ${x.retired_date?'已退役':'世界第 '+x.rank}</p></div><button onclick="profile(${x.id})">球员档案</button></div>${ratingPair(x)}</div><div class="card"><div class="row between"><h2>能力发展轨迹</h2><div class="periods">${[['90','近90天'],['365','近一年'],['all','全生涯']].map(([k,n])=>`<button class="${growthPeriod===k?'active':''}" onclick="setGrowthPeriod('${k}')">${n}</button>`).join('')}</div></div><div id="growthData" aria-live="polite"><p class="muted" style="padding:24px 0">读取成长记录…</p></div></div></div>`:`<div class="card empty"><h2>选择一名球员</h2><p class="muted">暂无个人档案，可在左侧搜索其他球员。</p></div>`}</div>`}
function growthList(){let query=growthSearch.trim().toLowerCase(),all=[...S.players,...S.retired].filter(x=>query?(x.name+' '+(x.zh||'')+' '+x.country+' '+(countries[x.country]||'')).toLowerCase().includes(query):isOwn(x.id));all.sort((a,b)=>Number(!!isOwn(b.id))-Number(!!isOwn(a.id))||Number(!!a.retired_date)-Number(!!b.retired_date)||a.rank-b.rank);return `<div class="growth-list-heading">${query?'搜索结果 · '+all.length:'球员档案 · '+all.length}</div>`+(all.map(x=>`<button class="growthpick ${x.id===growthId?'active':''}" onclick="chooseGrowth(${x.id})"><span><b>${full(x)}</b><small>${x.age}岁 · ${isOwn(x.id)?'本人':x.retired_date?'退役':'#'+x.rank}</small></span><span class="miniRatings"><b class="caText">${dec(x.ability)}</b><small class="paText">${paLabel(x)}</small></span></button>`).join('')||`<p class="muted growth-empty">${query?'无匹配球员':'暂无个人档案'}</p>`)+(query?'':'<p class="help growth-empty">输入姓名或国家，查询世界范围内的球员。</p>')}
function refreshGrowthList(){if($('growthList'))$('growthList').innerHTML=growthList()}
function chooseGrowth(id){growthId=id;render()}
function setGrowthPeriod(k){growthPeriod=k;render()}
async function loadGrowth(){let id=growthId,key=S.date+':'+id,req=++growthRequest;try{let d=growthCache.get(key);if(!d){let j=await rpc('growth',{id});if(j.error)throw Error(j.error);d=j.growth;growthCache.set(key,d)}if(req!==growthRequest||tab!=='growth'||id!==growthId||!$('growthData'))return;$('growthData').innerHTML=renderGrowth(d)}catch(e){if(req===growthRequest&&$('growthData'))$('growthData').innerHTML=`<p class="muted">${esc(e.message)}</p>`}}
function signed(v){return (v>=0?'+':'')+v.toFixed(2)}function deltaClass(v){return v>.00005?'positive':v<-.00005?'negative':'muted'}
function renderGrowth(d){let cutoff=growthPeriod==='all'?d.debut_date:addDays(d.date,-Number(growthPeriod)),rows=d.rows.filter(r=>r.date>cutoff&&r.date<=d.date),x=p(d.player_id),pa=paLabel(x),start=rows[0]?.ability_before??d.current_CA,change=d.current_CA-start,groups=[0,1,2].map(i=>rows.reduce((a,r)=>a+(r.group_delta?.[i]||0),0)),attrs=rows.filter(r=>r.attribute_delta),latest=rows.at(-1),phase={normal:'正常成长',fast:'快速成长',breakthrough:'突破期',plateau:'平台期'};let points=rows.length?[{date:addDays(rows[0].date,-7),v:start},...rows.map(r=>({date:r.date,v:r.ability_after}))]:[{date:d.date,v:d.current_CA}];let paRows=rows.filter(r=>r.pa_after);let exact=attrs.length===rows.length&&rows.length>0;let compare=attrs.length?Object.keys(x.attributes).map(k=>({k,v:attrs.reduce((s,r)=>s+(r.attribute_delta[k]||0),0),cur:x.attributes[k]})):[];return `<div class="growthmetrics"><div><small>区间 CA 变化</small><strong class="${deltaClass(change)}">${signed(change)}</strong><span>${start.toFixed(2)} → ${d.current_CA.toFixed(2)}</span></div><div><small>已记录成长周数</small><strong>${rows.length}</strong><span>${esc(latest?phase[latest.phase]||latest.phase:'尚无更新')}</span></div><div><small>生涯起点 / 出道至今</small><strong class="${deltaClass(d.current_CA-d.debut_CA)}">${signed(d.current_CA-d.debut_CA)}</strong><span>初始 CA ${d.debut_CA.toFixed(2)}</span></div></div>${growthChart(points)}<p class="help">CA纵轴随当前区间缩放，以便看清细微变化。每周更新一次；曲线只绘制引擎实际记录。${rows.length?'':' 尚未发生周度更新，请推进至少一周。'}</p><div class="growthgroups">${['技术能力','身体能力','心理与决策'].map((n,i)=>`<div><small>${n} · 组均值变化</small><strong class="${deltaClass(groups[i])}">${signed(groups[i])}</strong></div>`).join('')}</div><details class="compact-details growth-detail"><summary>16项属性成长明细</summary><div class="row between"><h3>属性变化</h3><small>${exact?'所选区间完整记录':attrs.length?'仅含新版记录周数 '+attrs.length:'暂无单项历史记录'}</small></div>${compare.length?`<p class="help">每项依次显示：当前评分 / 区间变化（属性点）。</p><div class="growthattrs">${compare.map(a=>`<div class="growthattr"><span>${esc(a.k)}</span><b>${a.cur.toFixed(2)}</b><b class="${deltaClass(a.v)}">${signed(a.v)}</b></div>`).join('')}</div>`:'<p class="help">旧版存档只记录了三类属性均值变化。新版开始逐周保存16项属性变化，不回填未记录的历史。</p>'}</details><details class="compact-details growth-detail"><summary>PA 预估历史</summary><div class="row between"><h3>潜力变化</h3><small>记录于周度成长更新</small></div>${paRows.length?`<div class="paHistory">${paRows.filter((r,i)=>i===0||r.pa_after.join()!==paRows[i-1].pa_after.join()||i===paRows.length-1).map(r=>`<span>${r.date} <b class="paText">${r.pa_after.join('–')}</b></span>`).join('')}</div>`:'<p class="help">当前PA已显示；更早的预估变化未被旧引擎保存。</p>'}</details><details class="compact-details growth-detail"><summary>最近周度更新</summary>${rows.length?`<div class="tablewrap growthtable"><table><thead><tr><th>日期</th><th>CA</th><th>变化</th><th>技术</th><th>身体</th><th>心理</th><th>阶段</th><th>近84天场次</th></tr></thead><tbody>${rows.slice(-12).reverse().map(r=>`<tr><td>${r.date}</td><td>${r.ability_after.toFixed(2)}</td><td class="${deltaClass(r.ability_after-r.ability_before)}">${signed(r.ability_after-r.ability_before)}</td>${r.group_delta.map(v=>`<td class="${deltaClass(v)}">${signed(v)}</td>`).join('')}<td>${phase[r.phase]||esc(r.phase)}</td><td>${r.matches_84d}</td></tr>`).join('')}</tbody></table></div>`:'<p class="help">尚无周度成长记录。</p>'}</details>${d.annual.length?`<div class="divider"></div><h3>历年年终 CA 与排名</h3><div class="paHistory">${d.annual.map(a=>`<span>${a.year} · CA <b>${a.CA.toFixed(2)}</b> · #${a.rank}</span>`).join('')}</div>`:''}`}
function growthChart(points){let lo=Math.min(...points.map(p=>p.v)),hi=Math.max(...points.map(p=>p.v)),pad=Math.max(.12,(hi-lo)*.12);lo=Math.floor((lo-pad)*10)/10;hi=Math.ceil((hi+pad)*10)/10;let t0=Date.parse(points[0].date),t1=Date.parse(points.at(-1).date),X=t=>62+(t1===t0?.5:(Date.parse(t)-t0)/(t1-t0))*678,Y=v=>20+(hi-v)/(hi-lo)*168,xy=points.map(p=>`${X(p.date)},${Y(p.v)}`),last=points.at(-1);return `<div class="growthchart"><svg viewBox="0 0 780 228" role="img" aria-label="CA成长曲线">${Array.from({length:5},(_,i)=>{let v=lo+(hi-lo)*i/4,y=Y(v);return `<line x1="62" y1="${y}" x2="740" y2="${y}" stroke="#dce1d5"/><text x="52" y="${y+4}" fill="#67746c" font-size="11" text-anchor="end">${v.toFixed(2)}</text>`}).join('')}${points.length>1?`<polygon points="${X(points[0].date)},188 ${xy.join(' ')} ${X(last.date)},188" fill="#71917b" opacity=".08"/><polyline points="${xy.join(' ')}" fill="none" stroke="#71917b" stroke-width="2.5" stroke-linejoin="round"/>`:''}${points.filter((_,i)=>points.length<=60||i%Math.ceil(points.length/60)===0||i===points.length-1).map(p=>`<circle cx="${X(p.date)}" cy="${Y(p.v)}" r="3" fill="#71917b"><title>${p.date} · CA ${p.v.toFixed(4)}</title></circle>`).join('')}<text x="62" y="211" fill="#67746c" font-size="11">${points[0].date}</text><text x="740" y="211" fill="#67746c" font-size="11" text-anchor="end">${last.date}</text></svg></div>`}



