// V8.1 event center: read-only views of the actual engine draw.
let eventCache=new Map(),eventId=null,eventDetail=null,eventLoading=false,eventError='',eventRequest=0,eventSection='auto',eventMine=false,eventDay='all';
function clearEventDetail(){eventDetail=null;eventError='';eventLoading=false;eventRequest++}
function selectEvent(id){if(eventId!==id){eventId=id;eventSection='auto';eventMine=false;eventDay='all';clearEventDetail();eventDetail=eventCache.get(id)||null}}
function eventDetails(id){if(busy)return;spatialVisual=null;spatialPaused=false;selectEvent(id);eventSection='auto';stopAuto();tab='event';showLast=false;$('modal').innerHTML='';closeProfile();render();window.scrollTo(0,0)}
async function loadEvent(){if(tab!=='event'||!eventId||eventDetail||eventLoading||eventError)return;let cached=eventCache.get(eventId);if(cached){eventDetail=cached;render();return;}let id=eventId,req=++eventRequest;eventLoading=true;try{let j=await rpc('event',{event:id});if(j.error)throw Error(j.error);if(req!==eventRequest||id!==eventId)return;eventDetail=j.detail;eventCache.set(id,j.detail)}catch(e){if(req===eventRequest)eventError=e.message}finally{if(req===eventRequest){eventLoading=false;if(tab==='event'){let el=$('eventBody');if(el)el.innerHTML=eventBody()}}}}
function eventTab(k){eventSection=k;let el=$('eventBody');if(el)el.innerHTML=eventBody()}
function eventPage(){if(!eventId)selectEvent(S.match?.event_id||nextEvent()?.id||S.calendar.at(-1)?.id);let e=eventDetail?.event||ev(eventId);let options=S.calendar.map(x=>`<option value="${esc(x.id)}" ${x.id===eventId?'selected':''}>${esc(x.name)} · ${x.start.slice(5)}</option>`).join('');return `<div class="event-toolbar"><button onclick="go('calendar')">← 赛事列表</button><select class="event-select" aria-label="选择赛事" onchange="eventDetails(this.value)">${!ev(eventId)&&e?`<option value="${esc(eventId)}" selected>${esc(e.name)} · 历史</option>`:''}${options}</select></div><div id="eventBody" class="event-body">${eventBody()}</div>`}
function enterLive(){if(!S.match)return advance(370);stopAuto();spatialVisual=null;spatialPaused=false;selectEvent(S.match.event_id);eventSection='auto';$('modal').innerHTML='';closeProfile();tab='match';showLast=false;render();window.scrollTo(0,0)}
let liveDetailOpen=false;
function currentEventSection(d,cur){let q=d.qualification,m=S.match?.event_id===d.event.id?S.match:null;if(m){if(['Q1','Q2'].includes(m.stage))return 'qual';if(/^G/.test(m.stage))return 'groups';if(KO_ROUNDS.includes(m.stage))return 'bracket'}if(cur&&['not_open','open','accepted'].includes(cur.phase))return 'entries';if(q&&!q.finished)return 'qual';if(d.groups.length&&!d.group_complete)return 'groups';if((d.schedule||[]).some(m=>KO_ROUNDS.includes(m.stage))||KO_ROUNDS.some(st=>Object.hasOwn(d.days||{},st)))return 'bracket';return 'entries'}
function eventBody(){let d=eventDetail,e=d?.event||ev(eventId),cur=ev(eventId),live=S.match?.event_id===eventId;if(!d)return `<section class="card event-banner"><div><h1>${e?esc(e.name):'赛事档案'}</h1><p>${e?esc(e.start)+' — '+esc(e.end):''}</p></div></section><section class="card event-placeholder">${eventError?`<h3>读取赛程失败</h3><p>${esc(eventError)}</p><button onclick="clearEventDetail();render()">重试</button>`:'<div class="spinner"></div><p>正在读取赛事赛程…</p>'}</section>`;e=d.event;let q=d.qualification,results=d.results||[],winner=d.placements&&Object.keys(d.placements).find(k=>d.placements[k]===0),current=currentEventSection(d,cur),available=[...(q?[['qual','资格赛']]:[]),...(d.groups.length?[['groups','小组赛']]:[]),...(KO_ROUNDS.some(st=>Object.hasOwn(d.days||{},st))||d.schedule.some(m=>KO_ROUNDS.includes(m.stage))?[['bracket','淘汰赛']]:[]),['schedule','每日赛程'],['entries','参赛名单']];let active=eventSection==='auto'||!available.some(([k])=>k===eventSection)?current:eventSection;let completed=cur?.status==='completed'||e.status==='completed',phase=completed?'已结束':cur?.status==='cancelled'||e.status==='cancelled'?'已取消':live?matchStage(S.match):current==='qual'?'资格赛':current==='groups'?'小组赛':current==='bracket'?'淘汰赛':cur?status(cur):'赛事档案';let own=(cur?.accepted||d.entries||[]).filter(isOwn);return `<section class="card event-banner event-compact"><div><div class="row">${lvl(e.level)}${badge(phase,'green')}<span class="muted">${esc(e.city||'')}</span></div><h1>${esc(e.name)}</h1><p>${esc(e.start)} — ${esc(e.end)} · ${results.length} 场已完成${own.length?' · 本人 '+own.length+' 人':''}</p></div><div class="event-banner-action">${live?`<small>${nm(S.match.a)} vs ${nm(S.match.b)}</small>${button('进入比赛 →','enterLive()','primary')}`:cur?.phase==='open'?button('确认 / 修改报名',`entry('${eventId}')`,'primary'):winner?`<button class="champion-label" onclick="showChampion({...eventDetail.event,champion:${+winner}})"><small>本届冠军 · 查看颁奖</small><strong>${nm(+winner)}</strong></button>`:''}</div></section><div class="event-tabs sectiontabs">${available.map(([k,n])=>`<button class="${active===k?'active':''}" onclick="eventTab('${k===current?'auto':k}')">${n}${k===current&&!completed?' <span class="current-dot" title="当前阶段"></span>':''}</button>`).join('')}</div>${active==='entries'?eventEntries(d,cur):active==='schedule'?schedulePanel(d):active==='groups'?groupTables(d):active==='bracket'?knockoutPanel(d):active==='qual'?`<section class="card stack"><h2>资格赛</h2>${qualificationPanel(q,d)}<details class="compact-details"><summary>资格赛比赛明细</summary>${qSchedule(d)||'<p class="muted">等待抽签</p>'}</details></section>`:eventEntries(d,cur)}` }
function eventEntries(d,cur){return `<section class="card stack"><h2>参赛名单</h2>${cur&&['accepted','drawn'].includes(cur.phase)?`<div class="row">${cur.accepted.filter(isOwn).filter(i=>!cur.withdrawn[String(i)]&&!cur.qualification?.eliminated?.[String(i)]&&!['eliminated','placement','champion'].includes(cur.sporting_status?.[String(i)]?.state)).map(i=>button('退出 '+(p(i).zh||p(i).name),`withdraw('${eventId}',${i})`,'small danger')).join('')}</div>`:''}<div class="tagrow">${entryNames(d.entries)}</div><div class="divider"></div><h3>候补名单</h3><div class="tagrow">${entryNames(d.reserves)}</div>${d.entries.length?'':'<p class="muted">报名审核后更新名单，抽签后公布对阵。</p>'}</section>`}
function eventResultMap(d){return new Map(d.results.map(r=>[r.serial,r]))}
function scoreFor(r,i){if(!r)return '—';if(r.outcome!=='played'&&r.outcome!=='retirement')return r.winner===i?'W':'—';let k=r.a===i?0:1;return r.history?.length?r.history.map(g=>g[k]).join(' · '):'—'}
function seedMark(d,id,qual=false){let n=(qual?d?.qual_seeds:d?.seeds)?.[String(id)];return n?`<span class="draw-seed" title="${qual?'资格赛':'赛事'}第${n}号种子">[${n}]</span>`:''}
function groupTables(d){let done=!!d.group_complete,k=d.advance_per_group||1;return `<section class="card stack"><div class="row between"><div><h2>小组赛积分榜</h2><small>每组前 ${k} 名晋级 · ${done?'最终排名':'实时排名'}</small></div>${badge(done?'已结束':'实时更新','green')}</div><div class="group-grid">${d.standings.map((g,i)=>`<article class="group-card"><header><strong>${String.fromCharCode(65+i)} 组</strong><small>${g.length} 人 · 每人 ${Math.max(0,g.length-1)} 场${d.draw_policy==='protected83'&&d.advance_per_group===1?' · '+(i<d.groups.length/2?'上半区':'下半区'):''}</small></header><div class="tablewrap"><table class="group-table"><thead><tr><th>名次</th><th>球员</th><th>场</th><th>胜</th><th>负</th><th>局差</th><th>分差</th></tr></thead><tbody>${g.map(z=>`<tr class="${z.rank&&z.rank<=k?'group-cut ':''}${isOwn(z.id)?'ownrow':''}${!z.rank?'group-out':''}"><td><span class="group-rank">${z.rank||'—'}</span></td><td><button class="link group-name" onclick="profile(${z.id})">${nm(z.id)}</button>${seedMark(d,z.id)}${isOwn(z.id)?'<span class="own-dot" title="本人"></span>':''}${!z.rank?'<small class="group-withdraw">退赛</small>':''}</td><td>${z.played}</td><td><b>${z.wins}</b></td><td>${z.losses}</td><td>${z.gd>0?'+':''}${z.gd}</td><td>${z.pd>0?'+':''}${z.pd}</td></tr>`).join('')}</tbody></table></div></article>`).join('')}</div><details class="compact-details"><summary>排名规则</summary><small>胜场优先；两人同胜场时比较相互战绩，否则比较局差、分差及${d.event.ruleset==='bwf84'?'预设抽签顺序':'签表顺序'}。三人组每人两场，赛程轮次不等于个人比赛场数。退赛/不可参赛球员及相关对阵按现有引擎规则处理。${d.draw_policy==='protected83'?(d.event.level==='FINALS'?' 总决赛小组头名分居半决赛，第二名重新抽签。':' 小组头名按赛前预设淘汰赛线路晋级，不按赛后排名重抽。'):''} 绿色标记为${done?'晋级':'暂居晋级区'}。</small></details></section>`}
const KO_ROUNDS=['R64','R32','R16','QF','SF','F'],KO_COUNTS={R64:32,R32:16,R16:8,QF:4,SF:2,F:1};
function bracketSide(pid,r,placeholder,d){let known=pid!=null,win=r&&known&&r.winner===pid;return `<div class="bracket-side ${win?'bracket-win':''} ${r&&known&&!win?'bracket-loss':''} ${known&&isOwn(pid)?'bracket-own':''}">${known?`<button class="link bracket-name" onclick="profile(${pid})" title="${nm(pid)}">${nm(pid)}${seedMark(d,pid)}</button>`:`<span class="bracket-name muted">${placeholder}</span>`}<span class="bracket-points">${known?scoreFor(r,pid):'—'}</span></div>`}
function knockoutPanel(d){let rounds=KO_ROUNDS.filter(st=>Object.hasOwn(d.days||{},st)||(d.schedule||[]).some(m=>m.stage===st)),rm=eventResultMap(d);if(!rounds.length)return `<section class="card stack"><h2>淘汰赛签表</h2><div class="empty">尚未抽签，正式签表将在抽签后公布。</div></section>`;let firstCount=KO_COUNTS[rounds[0]],height=firstCount*82,live=S.match?.event_id===d.event.id?S.match:null;let cols=rounds.map((st,i)=>{let matches=d.schedule.filter(m=>m.stage===st).sort((a,b)=>(a.slot??a.serial)-(b.slot??b.serial)),n=KO_COUNTS[st],stride=height/n;return `<div class="bracket-col"><div class="bracket-heading"><strong>${stage(st)}</strong><small>${(d.days[st]||matches[0]?.date||'').slice(5)||'—'}</small></div><div class="bracket-body" style="height:${height}px">${Array.from({length:n},(_,j)=>{let m=matches[j],r=m?rm.get(m.serial):null,hot=m&&live?.serial===m.serial;let placeholder=m?'轮空':i?'上轮胜者':d.groups.length?'小组晋级者':'待抽签';let preset=!m&&!i&&d.draw_policy==='protected83'&&d.main_slots?.length?[d.main_slots[j*2],d.main_slots[j*2+1]]:null;let pa=preset?preset[0]:m?.a,pb=preset?preset[1]:m?.b;let hint=(v,k)=>typeof v==='string'?'资格赛 '+v+' 胜者':preset?'轮空':!m&&!i&&d.draw_policy==='protected83'&&d.groups.length&&d.advance_per_group===1?String.fromCharCode(65+j*2+k)+' 组头名':placeholder;return `<div class="bracket-slot ${i<rounds.length-1?'bracket-connector':''} ${j%2?'lower':'upper'}" style="top:${(j+.5)*stride-34}px;--branch:${stride/2}px"><div class="bracket-match ${hot?'bracket-live':''}">${bracketSide(typeof pa==='number'?pa:null,r,hint(pa,0),d)}${bracketSide(typeof pb==='number'?pb:null,r,hint(pb,1),d)}<div class="bracket-status">${hot?'待赛':r?outcomes[r.outcome]||'完赛':m?'待进行':preset?'已抽签':'—'}</div></div></div>`}).join('')}</div></div>`}).join('');return `<section class="card stack"><div class="row between"><div><h2>淘汰赛树状签表</h2><small>${d.draw_policy==='protected83'?'种子保护 · 签位锁定 · 胜者沿连线晋级':'历史签表 · 胜者沿连线晋级'}</small></div><small>横向滚动查看完整签表 →</small></div><div class="bracket-scroll" tabindex="0" aria-label="淘汰赛树状签表"><div class="bracket-tree">${cols}</div></div><small>绿色为胜者，左侧色条标记生涯球员比赛；[数字] 为赛前冻结的种子编号。未确认的资格赛或小组晋级者保留通道签位。</small></section>`}
function qSchedule(d){let rows=d.schedule.filter(m=>['Q1','Q2'].includes(m.stage));if(!rows.length)return '';return `<div class="tablewrap"><table class="schedule-table"><thead><tr><th>轮次</th><th>对阵</th><th>比分</th><th>状态</th></tr></thead><tbody>${rows.map(m=>scheduleRow(d,m,true)).join('')}</tbody></table></div>`}
function scheduleRow(d,m,short=false){let r=d.results.find(r=>r.serial===m.serial),live=S.match?.event_id===d.event.id&&S.match.serial===m.serial,own=isOwn(m.a)||isOwn(m.b);return `<tr class="${own?'ownrow':''}"><td>${short?'':`<small>${esc(m.date.slice(5))}</small> · `}${matchStage(m,d)}${/^G\d+$/.test(m.stage)?`<small class="schedule-round">赛程第${m.stage.slice(1)}轮</small>`:''}</td><td><span class="${r?.winner===m.a?'match-winner':''}">${m.a==null?'轮空':`<button class="link" onclick="profile(${m.a})">${nm(m.a)}${seedMark(d,m.a,['Q1','Q2'].includes(m.stage))}</button>`}</span><span class="muted match-vs">vs</span><span class="${r?.winner===m.b?'match-winner':''}">${m.b==null?'轮空':`<button class="link" onclick="profile(${m.b})">${nm(m.b)}${seedMark(d,m.b,['Q1','Q2'].includes(m.stage))}</button>`}</span></td><td class="schedule-score">${r?.history?.map(g=>g.join(':')).join(' / ')||'—'}</td><td>${live?button('进入比赛',"go('match')",'primary small'):badge(r?outcomes[r.outcome]||'完赛':'待进行',r?'green':'')}</td></tr>`}
function schedulePanel(d){let days=[...new Set([...Object.values(d.days||{}),...d.schedule.map(m=>m.date)])].sort();let rows=d.schedule.filter(m=>(eventDay==='all'||m.date===eventDay)&&(!eventMine||isOwn(m.a)||isOwn(m.b)));let future=Object.entries(d.days||{}).filter(([st,date])=>!d.schedule.some(m=>m.stage===st)&&(!eventMine)&&(eventDay==='all'||date===eventDay));return `<section class="card stack" id="schedulePanel"><div class="row between"><div><h2>每日赛程</h2><small>已生成比赛与未来轮次安排</small></div><div class="row"><select aria-label="赛程日期" onchange="eventDay=this.value;refreshSchedule()"><option value="all">所有日期</option>${days.map(day=>`<option value="${day}" ${day===eventDay?'selected':''}>${day.slice(5)}${day===S.date?' · 今日':''}</option>`).join('')}</select><label class="row"><input type="checkbox" ${eventMine?'checked':''} onchange="eventMine=this.checked;refreshSchedule()">仅生涯球员比赛</label></div></div>${rows.length||future.length?`<div class="tablewrap"><table class="schedule-table"><thead><tr><th>日期 / 轮次</th><th>球员对阵</th><th>比分</th><th>状态</th></tr></thead><tbody>${[...rows.map(m=>({date:m.date,serial:m.serial,html:scheduleRow(d,m)})),...future.map(([st,date])=>({date,serial:9999,html:`<tr><td><small>${date.slice(5)}</small> · ${roundLabel(st)}</td><td class="muted">对阵待生成</td><td>—</td><td>${badge('轮次计划')}</td></tr>`}))].sort((a,b)=>a.date.localeCompare(b.date)||a.serial-b.serial).map(x=>x.html).join('')}</tbody></table></div>`:`<div class="empty">${eventMine?'当前筛选下没有生涯球员比赛':'等待抽签公布具体赛程'}</div>`}</section>`}
function refreshSchedule(){let el=$('schedulePanel');if(el&&eventDetail)el.outerHTML=schedulePanel(eventDetail)}
function stableScoreboard(m,a,b,score,server,last){let noScore=m.finished&&['bye','walkover','void'].includes(m.outcome);return `<div class="court stable-court"><div class="scoregrid">${[a,b].map((x,i)=>`<div class="score-player"><small class="score-country">${esc(x?.country||'')} ${isOwn(x?.id)?'· 本人':''}</small><h2 class="score-name" title="${nm(x?.id)}">${nm(x?.id)}</h2><div class="score">${noScore?'—':score[i]}</div><div class="serve-slot"><span class="serve ${!m.finished&&server===i?'':'serve-inactive'}">${!m.finished&&server===i?'● 发球 · '+(score[i]%2?'左':'右')+'区':'CA '+dec(x?.ability)}</span></div></div>${i===0?`<div class="score-mid"><small>局分</small><div class="game-score">${noScore?'—':m.games.join(' : ')}</div><small>${m.finished?'比赛结束':'第 '+(spatialVisual?.r.game??(m.history.length+1))+' 局'}</small></div>`:''}`).join('')}</div><div class="fixed-games">${Array.from({length:3},(_,i)=>`<div class="game-tile ${m.history[i]?'game-done':''}"><small>第${i+1}局</small><b>${m.history[i]?m.history[i].join(' : '):'— : —'}</b></div>`).join('')}</div><div class="score-comment">${m.finished?`<strong>${m.winner?nm(m.winner)+' 获胜':'无胜者'}</strong>`:last?`<small>上一分：${nm(last.winner===0?m.a:m.b)} · ${terminals[last.terminal]} · ${last.shots} 拍${last.service_over?' · 换发球':''}${last.changed_ends?' · 换边':''}</small>`:'<small>等待首个回合，发球方由引擎随机决定</small>'}</div></div>`}

